    (rax t0 t1 t2 a0 a1 a2 a3 a4 a6 a7 xs2 xs5 xs7 xs8 xs10 xs11 t3 t4 t5 t6 : word),
  rw_cells asegs m2 spa [CB 8 p0; CB 8 p8; C8 (Z_to_bv 64 ff); CB 8 p24; C8 (Z_to_bv 64 ff); CB 16 pL] ->
  rw_cells asegs m2 (spa + 56) gap -> Z.of_nat (cells_size gap) = bv_unsigned sp + -104 - (spa + 56) ->
  (spa = bv_unsigned sp + -160 \/ spa = bv_unsigned sp + -176) ->
  rw_cells asegs m2 (bv_unsigned sp + -104) (sc_saved s11 s10 s9 s8 s7 s6 s5 s4 s3 s2 s1 s0 ra) ->
  rw_cells asegs m2 ff [CB 32 h32; CB 88 j88; C8 (Z_to_bv 64 fp)] -> rw_cells asegs m2 (Z.shiftr ff 3 + 2147450880) [CB 16 shb] -> rw_cells asegs m2 fp [C1 (b8 1)] ->
