  as_RFS H ((1, ff, fp) :: LF) m2 -> fresh_frame H LF 1 ff fp -> ACONST m2 -> stack0 m2 lo shi ->
  munch ([(lo, bv_unsigned sp)]%Z ++ fr1_XS H ff fp) m m2 -> wmono asegs m m2 ->
  AScheduler LB m2 S Sv -> sch_lk Sv = 0 -> as_RHEAP H s LB m2 -> as_RFS H LF m ->
  lo + ASHUT_STACK <= bv_unsigned sp -> aceil <= lo -> bv_unsigned ra mod 2 = 0 -> bv_unsigned sp mod 16 = 0 -> bv_unsigned sp <= shi ->
  evt asegs (asched_shutdown_post H ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc s LB LF S lo shi Sv m)
